8	const _barCount = 12;
9	const _staggerPerBar = math.pi / 6;
10	
11	/// Reads `AudioCaptureRepository.amplitudeStream` directly via `get_it` —
12	/// the one sanctioned bypass of "always through the bloc" for this unit,
13	/// since the amplitude signal is too high-frequency to belong in bloc event
14	/// history (contracts/audio-capture-repository.md). The live amplitude sets
15	/// the bars' overall scale; a looping, per-bar phase offset staggers their
16	/// motion into a traveling wave instead of all 12 moving in lockstep.
17	class AudioWaveform extends StatefulWidget {
18	  const AudioWaveform({super.key});
19	
20	  @override
21	  State<AudioWaveform> createState() => _AudioWaveformState();
22	}
23	
24	class _AudioWaveformState extends State<AudioWaveform>
25	    with SingleTickerProviderStateMixin {
26	  late final AnimationController _controller;
27	
28	  @override
29	  void initState() {
30	    super.initState();
31	    _controller = AnimationController(
32	      vsync: this,
33	      duration: const Duration(milliseconds: 1600),
34	    )..repeat();
35	  }
36	
37	  @override
38	  void dispose() {
39	    _controller.dispose();
40	    super.dispose();
41	  }
42	
43	  @override
44	  Widget build(BuildContext context) {
45	    final repository = getIt<AudioCaptureRepository>();
46	    return StreamBuilder<double>(
47	      stream: repository.amplitudeStream,
48	      builder: (context, snapshot) {
49	        final amplitudeDbfs = snapshot.data ?? -45.0;
50	        final normalized = ((amplitudeDbfs + 60) / 60).clamp(0.0, 1.0);
51	        return AnimatedBuilder(
52	          animation: _controller,
53	          builder: (context, child) {
54	            final phase = _controller.value * 2 * math.pi;
55	            return Row(
56	              mainAxisAlignment: MainAxisAlignment.center,
57	              children: List.generate(_barCount, (index) {
58	                final wave =
59	                    (math.sin(phase - index * _staggerPerBar) + 1) / 2;
60	                final height =
61	                    DesignTokens.spacingSm +
62	                    (0.25 + 0.75 * wave) * normalized * DesignTokens.spacingXl;
63	                return Padding(
64	                  padding: const EdgeInsets.symmetric(
65	                    horizontal: DesignTokens.spacingXs,
66	                  ),
67	                  child: Container(
68	                    width: DesignTokens.spacingXs,
69	                    height: height,
70	                    decoration: BoxDecoration(
71	                      color: DesignTokens.colorSecondary,
72	                      borderRadius: BorderRadius.circular(
73	                        DesignTokens.radiusSm,
74	                      ),
75	                    ),
76	                  ),
77	                );
78	              }),
79	            );
80	          },
81	        );
82	      },
83	    );
84	  }
85	}
